#include "gemm/gemm_gpu.hpp"

#include <cmath>
#include <vector>

#include "gemm/gemm_host.hpp"
#include "gpu_util/gpu_blas_api.hpp"
#include "gpu_util/gpu_blas_handle.hpp"
